if __name__=='__main__':
    sources=json.loads((ROOT/'data/sources.json').read_text(encoding='utf-8'))
    by_name={s['name']:s for s in sources}
    for t in talks:
        source=by_name[t['filename']];t['source_url']=source['url'];t['source_id']=source['id']
        text=json.loads((ROOT/'data/extracted'/(Path(t['filename']).stem+'.json')).read_text(encoding='utf-8'))
        t['pages']=len(text['pages']);t['ocr_pages']=sum(p.get('method')=='local-tesseract' for p in text['pages'])
        for lesson in t['lessons']: assert 1<=lesson['page']<=t['pages']
    assert len(talks)==len(sources)==19
    (ROOT/'data/talks.json').write_text(json.dumps(talks,ensure_ascii=False,indent=2),encoding='utf-8')
    print('Editorial cards:',len(talks))
